// // // // // // // // // // // // // //       )}

// // // // // // // // // // // // // //       {/* edit name modal */}
// // // // // // // // // // // // // //       <Modal visible={editOpen} transparent animationType="fade" onRequestClose={() => setEditOpen(false)}>
// // // // // // // // // // // // // //         <Pressable style={styles.modalBackdrop} onPress={() => !saving && setEditOpen(false)}>
// // // // // // // // // // // // // //           <Pressable style={styles.modalCard} onPress={() => {}}>
// // // // // // // // // // // // // //             <Text style={styles.modalTitle}>Edit profile</Text>
// // // // // // // // // // // // // //             <Text style={styles.modalLabel}>Display name</Text>
// // // // // // // // // // // // // //             <TextInput
// // // // // // // // // // // // // //               value={draftName}
// // // // // // // // // // // // // //               onChangeText={setDraftName}
// // // // // // // // // // // // // //               maxLength={30}
// // // // // // // // // // // // // //               autoFocus
// // // // // // // // // // // // // //               placeholder="Your name"
// // // // // // // // // // // // // //               placeholderTextColor="#5B6499"
// // // // // // // // // // // // // //               style={styles.input}
// // // // // // // // // // // // // //               onSubmitEditing={saveName}
// // // // // // // // // // // // // //               returnKeyType="done"
// // // // // // // // // // // // // //             />
// // // // // // // // // // // // // //             {editError ? <Text style={styles.modalError}>{editError}</Text> : null}
// // // // // // // // // // // // // //             <View style={styles.modalButtons}>
// // // // // // // // // // // // // //               <TouchableOpacity
// // // // // // // // // // // // // //                 style={styles.modalCancel}
// // // // // // // // // // // // // //                 onPress={() => setEditOpen(false)}
// // // // // // // // // // // // // //                 disabled={saving}
// // // // // // // // // // // // // //                 activeOpacity={0.8}
// // // // // // // // // // // // // //               >
// // // // // // // // // // // // // //                 <Text style={styles.modalCancelText}>Cancel</Text>
// // // // // // // // // // // // // //               </TouchableOpacity>
// // // // // // // // // // // // // //               <TouchableOpacity style={styles.modalSave} onPress={saveName} disabled={saving} activeOpacity={0.85}>
// // // // // // // // // // // // // //                 {saving ? <ActivityIndicator color="#FFFFFF" /> : <Text style={styles.modalSaveText}>Save</Text>}
// // // // // // // // // // // // // //               </TouchableOpacity>
// // // // // // // // // // // // // //             </View>
// // // // // // // // // // // // // //           </Pressable>
// // // // // // // // // // // // // //         </Pressable>
// // // // // // // // // // // // // //       </Modal>
// // // // // // // // // // // // // //     </LinearGradient>
// // // // // // // // // // // // // //   );
// // // // // // // // // // // // // // };

